<template>
 <div class="qsw-page">
  <div class="qsw-inner">
   <header class="qsw-hero"><div><p class="qsw-eyebrow">QGAUSS / MAKE IT FEEL RIGHT</p><h1>{{st('一处微调，让整站更合拍。')}}</h1><p class="qsw-intro">{{st('把站点的个性、创作节奏和服务规则，放在一处照顾。')}}</p><div class="qsw-numbers"><span><b>{{groups.length||'—'}}</b>{{st('个分组')}}</span><span><b>{{items.length||'—'}}</b>{{st('项设置')}}</span><span :class="{'has-change':changes.length}"><b>{{changes.length}}</b>{{st('项待保存')}}</span></div></div><div class="qsw-sculpture" aria-hidden="true"><div class="qsw-ring"></div><i class="qsw-dot"></i><div class="qsw-sculpture-back"></div><div class="qsw-sculpture-face"><ClientIcon name="settings"/><span>QGAUSS</span><b>✦</b></div><div class="qsw-mini-switch"><i></i></div></div></header>
   <section class="qsw-services" :aria-label="st('服务准备状态')"><div v-for="service in serviceLabels" :key="service.key" class="qsw-service"><span class="qsw-service-icon"><ClientIcon :name="service.icon"/></span><div><b>{{st(service.label)}}</b><small><i :class="{ready:policies[service.key].known&&policies[service.key].ready}"></i>{{st(!policies[service.key].known?'待核对':policies[service.key].ready?'配置已准备':'尚未开放')}}</small></div></div><router-link to="/mail" class="qsw-link">{{st('前往邮件中心')}}<ClientIcon name="arrowUpRight"/></router-link></section>
   <p class="qsw-readiness-note">{{st('配置准备状态不代表真实投递或扫码已经验收。')}}</p>
   <p v-if="!auth.isAdmin" class="qsw-feedback qsw-error" role="alert">{{st('当前账号没有管理权限。')}}</p>
   <section v-if="pending" class="qsw-pending" aria-live="polite"><span class="qsw-pending-icon"><ClientIcon name="info"/></span><div><h2>{{st('有一项保存结果待确认')}}</h2><p>{{st('先核对原申请，再开始下一次调整。')}}</p></div><div class="qsw-button-row"><button type="button" class="qsw-button qsw-primary" :disabled="busy" @click="checkPending">{{st(checking?'正在核对':'核对原结果')}}</button><button type="button" class="qsw-button" :disabled="busy" @click="closing=true">{{st('结束这次等待')}}</button></div></section>
   <section v-if="receipt?.status==='applied'" class="qsw-success" aria-live="polite"><ClientIcon name="check"/><div><b>{{st('已保存 {count} 项设置',{count:receipt.items.length})}}</b><small>{{formatDate(receipt.appliedAt)}}</small><details><summary>{{st('查看本次结果')}}</summary><dl v-for="item in receipt.items" :key="item.key"><dt>{{title(item)}}</dt><dd>{{item.sensitive?st(item.afterConfigured?'已填写':'未填写'):formatValue(item,item.after)}}</dd></dl></details></div></section>
   <p v-else-if="notice" class="qsw-feedback qsw-good" role="status">{{st(notice)}}</p>
   <p v-if="error" class="qsw-feedback qsw-error" role="alert">{{st(error)}}</p>
   <div class="qsw-workspace">
    <aside class="qsw-sidebar"><div class="qsw-sidebar-title"><span>{{st('设置工作台')}}</span><button type="button" class="qsw-icon-button" :disabled="busy||loading" :aria-label="st('重新读取')" @click="refresh"><ClientIcon name="refresh"/></button></div><nav class="qsw-groups" :aria-label="st('设置分组')"><button type="button" :class="{active:group==='all'&&!query.trim()}" @click="chooseGroup('all')"><span class="qsw-group-icon"><ClientIcon name="layout"/></span><b>{{st('全部设置')}}</b><small>{{items.length}}</small></button><button v-for="name in groups" :key="name" type="button" :class="{active:group===name&&!query.trim()}" :aria-current="group===name&&!query.trim()?'page':undefined" @click="chooseGroup(name)"><span class="qsw-group-icon"><ClientIcon :name="SETTINGS_GROUPS[name].icon"/></span><b>{{st(SETTINGS_GROUPS[name].label)}}</b><small :class="{'is-dirty':dirtyInGroup(name)}">{{dirtyInGroup(name)||items.filter(item=>item.group===name).length}}</small></button></nav></aside>
    <main class="qsw-main"><div class="qsw-section-head"><div><span class="qsw-eyebrow">YOUR SPACE, YOUR WAY</span><h2>{{st(query.trim()?'跨分组搜索':group==='all'?'全部设置':SETTINGS_GROUPS[group]?.label||'设置工作台')}}</h2></div><label class="qsw-search"><ClientIcon name="search"/><input v-model="query" type="search" :aria-label="st('搜索设置名称或用途')" :placeholder="st('搜索设置名称或用途')"/><button v-if="query" type="button" class="qsw-icon-button" :aria-label="st('清除搜索')" @click="query=''"><ClientIcon name="close"/></button></label></div>
     <div v-if="loading&&!items.length" class="qsw-loading"><BrandLoader :size="56" :text="st('正在读取设置')"/></div>
     <div v-if="loadError" class="qsw-feedback qsw-error" role="alert">{{st(loadError)}}<button type="button" class="qsw-button" :disabled="loading||busy" @click="refresh">{{st('重新读取')}}</button></div>
     <div v-if="!loading&&items.length&&!visible.length" class="qsw-empty"><ClientIcon name="search"/><h3>{{st('没有找到匹配的设置')}}</h3><p>{{st('换个词，或回到分组看看。')}}</p></div>
     <div class="qsw-fields"><article v-for="item in visible" :key="item.key" class="qsw-field" :class="{'is-edited':isEdited(item),'has-conflict':!!conflicts[item.key],'has-error':!!problems[item.key]}" :data-setting="item.key"><div class="qsw-field-top"><div class="qsw-field-title"><label :id="fieldId(item)+'-label'" :for="fieldId(item)">{{title(item)}}</label><div class="qsw-badges"><span>{{st(item.public?'前台可见':'仅管理端')}}</span><span v-if="isEdited(item)" class="qsw-edited">{{st('本次已改动')}}</span></div></div><label v-if="item.type==='boolean'" class="qsw-switch"><input :id="fieldId(item)" v-model="draft[item.key]" type="checkbox" role="switch" :aria-labelledby="fieldId(item)+'-label'" :disabled="locked||emailLocked(item)"/><span aria-hidden="true"><i></i></span><b aria-hidden="true">{{st(draft[item.key]?'开启':'关闭')}}</b></label></div>
      <p v-if="hint(item.key)" :id="fieldId(item)+'-hint'" class="qsw-hint">{{hint(item.key)}}</p>
      <template v-if="item.type!=='boolean'"><textarea v-if="multiline.has(item.key)" :id="fieldId(item)" v-model="draft[item.key]" :maxlength="item.maxLength" :disabled="locked" :rows="item.key==='upload.allowedMime'?4:3" :aria-invalid="!!problems[item.key]" :aria-describedby="fieldId(item)+'-hint'"></textarea><input v-else-if="item.type==='number'" :id="fieldId(item)" v-model.number="draft[item.key]" type="number" :step="item.integer?1:'any'" :min="item.min" :max="item.max" inputmode="decimal" :disabled="locked" :aria-invalid="!!problems[item.key]"/><input v-else :id="fieldId(item)" v-model="draft[item.key]" :type="item.sensitive?'password':'text'" autocomplete="off" :maxlength="item.maxLength" :disabled="locked" :aria-invalid="!!problems[item.key]"/></template>
      <p v-if="item.key==='security.emailVerificationRequired'&&emailLocked(item)" class="qsw-field-note">{{st('先准备发件设置，才可开启邮箱必验。')}}</p><p v-if="item.sensitive" class="qsw-field-note">{{st('邀请码不会保留在页面草稿中。')}}</p>
      <div class="qsw-field-meta"><small>{{st('默认')}} · {{formatValue(item,item.defaultValue)}}<template v-if="item.type==='number'&&(item.min!==undefined||item.max!==undefined)"><span> · {{st('范围')}} {{item.min??'—'}} – {{item.max??'∞'}}</span></template></small><button type="button" :disabled="locked||draft[item.key]===item.defaultValue||item.key==='security.emailVerificationRequired'&&item.defaultValue===true&&emailLocked(item)" @click="restoreDefault(item)">{{st('使用默认值')}}</button></div>
      <p v-if="problems[item.key]" :id="fieldId(item)+'-error'" class="qsw-field-error" role="alert">{{st(problems[item.key])}}</p>
      <section v-if="conflicts[item.key]" class="qsw-conflict"><h3><ClientIcon name="info"/>{{st('这项设置已有变化')}}</h3><dl><div><dt>{{st('最新内容')}}</dt><dd>{{formatValue(item,conflicts[item.key].value)}}</dd></div><div><dt>{{st('你的修改')}}</dt><dd>{{formatValue(item,draft[item.key])}}</dd></div></dl><div class="qsw-button-row"><button type="button" class="qsw-button" :disabled="locked" @click="resolve(item.key,'latest')">{{st('采用最新内容')}}</button><button type="button" class="qsw-button" :disabled="locked" @click="resolve(item.key,'mine')">{{st('保留我的修改，重新核对')}}</button></div></section>
     </article></div>
    </main>
   </div>
   <footer class="qsw-actions" :class="{'has-edits':changes.length||conflictCount}"><div><span class="qsw-action-dot" :class="{changed:changes.length}"></span><div><b>{{st(conflictCount?'有 {count} 项变化需要核对':changes.length?'有 {count} 项改动等待保存':'还没有需要保存的改动。',{count:conflictCount||changes.length})}}</b><small>{{readAt?st('最后读取')+' '+formatDate(readAt):st('只会保存这次确认的改动。')}}</small></div></div><button ref="previewButton" type="button" class="qsw-button qsw-primary" :disabled="locked||busy||loading||!changes.length" @click="openReview">{{st('预览这次调整')}}<ClientIcon name="arrow"/></button></footer>
  </div>
  <dialog ref="dialog" class="qsw-dialog" :aria-label="st(closing?'结束这次等待':'核对本次调整')" @cancel.prevent="cancelDialog"><template v-if="review||closing"><header><div><span class="qsw-eyebrow">QGAUSS / ONE CLEAR DECISION</span><h2>{{st(closing?'结束这次等待':'核对本次调整')}}</h2></div><button type="button" class="qsw-icon-button" :disabled="busy" :aria-label="st('关闭预览')" @click="cancelDialog"><ClientIcon name="close"/></button></header><p>{{st(closing?'只结束尚未保存的申请；已经保存的设置会保留。':'确认后一次保存；未选中的设置保持现状。')}}</p><div v-if="review&&!closing" class="qsw-review-list"><article v-for="item in review.rows" :key="item.key"><h3>{{title(item)}}</h3><dl><div><dt>{{st('修改前')}}</dt><dd>{{formatValue(item,item.before)}}</dd></div><span aria-hidden="true">→</span><div><dt>{{st('修改后')}}</dt><dd>{{formatValue(item,item.after)}}</dd></div></dl></article></div><p v-if="error" class="qsw-feedback qsw-error" role="alert">{{st(error)}}</p><footer><button type="button" class="qsw-button" :disabled="busy" @click="cancelDialog">{{st(closing?'继续核对':'返回调整')}}</button><button type="button" class="qsw-button qsw-primary" :disabled="busy" @click="closing?conclude():confirm()"><ClientIcon :name="busy?'refresh':closing?'close':'check'"/>{{st(saving?'正在保存':closing?'确认结束':'确认保存')}}</button></footer></template></dialog>
 </div>
</template>
<script setup>
import {nextTick,onBeforeUnmount,ref,watch} from 'vue';
import {useRoute} from 'vue-router';
import {useAuth} from '../../stores/auth.js';
import {currentLang} from '../../i18n/index.js';
import {settingsHint,settingsText,settingsTitle} from '../../i18n/settings-messages.js';
import {SETTINGS_GROUPS} from '../../lib/settings-workspace.js';
import {useSettingsWorkspace} from '../../composables/useSettingsWorkspace.js';
import ClientIcon from '../reference/ClientIcon.vue';
import BrandLoader from './BrandLoader.vue';
import './settings-workspace.css';
const auth=useAuth(),state=useSettingsWorkspace(),{items,draft,bases,conflicts,query,group,groups,visible,loading,saving,checking,busy,locked,loadError,error,notice,readAt,pending,receipt,review,closing,policies,changes,problems,conflictCount,refresh,chooseGroup,resolve,restoreDefault,openReview,confirm,checkPending,conclude}=state,dialog=ref(null),previewButton=ref(null),multiline=new Set(['site.welcome','site.announcement','upload.allowedMime','upstream.hostAllowlist']);
const serviceLabels=[{key:'mail',label:'邮箱发件',icon:'mail'},{key:'phone',label:'手机验证',icon:'lock'},{key:'external',label:'扫码登录',icon:'user'}],st=(text,params)=>settingsText(currentLang.value,text,params),title=item=>settingsTitle(currentLang.value,item.key,item.description),hint=key=>settingsHint(currentLang.value,key),fieldId=item=>'qsw-setting-'+item.key.replaceAll('.','-'),isEdited=item=>draft[item.key]!==bases[item.key]?.value,dirtyInGroup=name=>changes.value.filter(row=>items.value.find(item=>item.key===row.key)?.group===name).length,emailLocked=item=>item.key==='security.emailVerificationRequired'&&draft[item.key]!==true&&(!policies.mail.known||!policies.mail.ready),formatDate=value=>new Date(value).toLocaleString(currentLang.value==='en'?'en-US':currentLang.value==='zh-TW'?'zh-TW':'zh-CN',{hour12:false});
const route=useRoute();
watch([()=>route.query.group,()=>items.value.length>0],([name,loaded])=>{if(loaded&&groups.value.includes(name))chooseGroup(name);},{immediate:true});
function formatValue(item,value){if(item.sensitive)return st(value?'已填写':'未填写');if(typeof value==='boolean')return st(value?'开启':'关闭');return value===''?st('未填写'):String(value);}
function cancelDialog(){if(busy.value)return;review.value=null;closing.value=false;}
watch(()=>!!review.value||closing.value,async open=>{await nextTick();if(!dialog.value)return;if(open&&!dialog.value.open)dialog.value.showModal();else if(!open&&dialog.value.open){dialog.value.close();previewButton.value?.focus();}});
onBeforeUnmount(()=>{if(dialog.value?.open)dialog.value.close();});
</script>
